(function(){
  const J=()=>{try{return pm.response.json()}catch(e){return null}};
  const status=c=>pm.test('status '+c,()=>pm.response.to.have.status(c));
  const oneOf=cs=>pm.test('status en ['+cs.join(',')+']',()=>pm.expect(cs).to.include(pm.response.code));
  const problem=(c,t)=>{status(c);
    pm.test('Problem Details RFC 9457 (application/problem+json)',()=>{
      pm.expect(pm.response.headers.get('Content-Type')||'').to.include('application/problem+json');
      const b=J(); pm.expect(b,'cuerpo JSON').to.be.an('object');
      pm.expect(b.type,'type').to.be.a('string').and.match(/^https?:\/\//);
      pm.expect(b.title,'title').to.be.a('string').and.not.empty;
      pm.expect(b.status,'status del cuerpo').to.eql(c);
      pm.expect(b.detail,'detail').to.be.a('string');
      pm.expect(b.instance,'instance').to.be.a('string').and.match(/^\//);
      if(t) pm.expect(b.type).to.match(new RegExp(t+'$'));
    });
    noLeak();};
  const noLeak=()=>pm.test('Sin trazas ni detalles internos en la respuesta',()=>{
      pm.expect(pm.response.text()).to.not.match(/Exception|\bat (ar|org|java|jakarta)\.|\.java:\d+|hibernate|PSQLException|org\.springframework/i);});
  const known=(id,desc,secureOk)=>{ if(secureOk) pm.test('['+id+'] corregido: '+desc,()=>{}); else pm.test.skip('['+id+'] DEFECTO CONOCIDO (falla esperada): '+desc); };
  const b64u=s=>CryptoJS.enc.Base64.stringify(CryptoJS.enc.Utf8.parse(s)).replace(/=+$/,'').replace(/\+/g,'-').replace(/\//g,'_');
  const sig=(data,secret)=>CryptoJS.enc.Base64.stringify(CryptoJS.HmacSHA256(data,secret)).replace(/=+$/,'').replace(/\+/g,'-').replace(/\//g,'_');
  const forge=(o)=>{ const now=Math.floor(Date.now()/1000);
    const h=b64u(JSON.stringify({alg:o.alg||'HS256',typ:'JWT'}));
    const p=b64u(JSON.stringify({sub:'u-1002',nationalId:'30222333',role:o.role||'ADMINISTRADOR',iat:now-7200,exp:now+(o.exp===undefined?3600:o.exp)}));
    const s=o.alg==='none'?'':sig(h+'.'+p,o.secret||'x'.repeat(40));
    return h+'.'+p+'.'+s; };
  const fetchEtag=(path,tokVar,varName)=>{ pm.sendRequest({url:pm.variables.replaceIn('{{base_url}}/api/v1'+path),method:'GET',
      header:{Authorization:'Bearer '+pm.variables.get(tokVar)}},(e,r)=>{ pm.collectionVariables.set(varName,(r&&r.headers.get('ETag'))||''); }); };
  return {J,status,oneOf,problem,noLeak,known,forge,b64u,fetchEtag};
})()

